using System;
using System.IO;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD ERRORS ===");
        build.VisitAllChildren<Error>(error =>
        {
            Console.WriteLine($"[ERROR] {error.File}({error.LineNumber},{error.ColumnNumber}): {error.Code}: {error.Text}");
            // Show project context
            var parent = error.Parent;
            while (parent != null && parent is not Project)
                parent = parent.Parent;
            if (parent is Project proj)
                Console.WriteLine($"  in project: {proj.ProjectFile}");
            Console.WriteLine();
        });

        Console.WriteLine("\n=== BUILD WARNINGS (first 30) ===");
        int warnCount = 0;
        build.VisitAllChildren<Warning>(warning =>
        {
            if (warnCount++ < 30)
                Console.WriteLine($"[WARN] {warning.File}({warning.LineNumber}): {warning.Code}: {warning.Text}");
        });

        Console.WriteLine($"\nTotal warnings: {warnCount}");
        Console.WriteLine($"\nBuild succeeded: {build.Succeeded}");
    }
}
EOF

