using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        // Look at package references in Services project
        Console.WriteLine("=== PACKAGE REFERENCES IN SERVICES ===");
        build.VisitAllChildren<NamedNode>(node =>
        {
            if (node.Name == "PackageReference" && node is AddItem addItem)
            {
                var parent = (BaseNode)node;
                while (parent != null && parent is not Project)
                    parent = parent.Parent as BaseNode;
                if (parent is Project proj && proj.ProjectFile?.Contains("Services") == true)
                {
                    foreach (var child in addItem.Children.OfType<Item>())
                        Console.WriteLine($"  {child.Text}");
                }
            }
        });

        // Look at all items to find references
        Console.WriteLine("\n=== REFERENCES IN SERVICES PROJECT ===");
        build.VisitAllChildren<AddItem>(item =>
        {
            var parent = (BaseNode)item;
            while (parent != null && parent is not Project)
                parent = parent.Parent as BaseNode;
            if (parent is Project proj && proj.ProjectFile?.Contains("Services") == true)
            {
                if (item.Name.Contains("Reference") || item.Name.Contains("Package"))
                {
                    foreach (var child in item.Children.OfType<Item>())
                        Console.WriteLine($"  [{item.Name}] {child.Text}");
                }
            }
        });

        // Look at source file content embedded in binlog
        Console.WriteLine("\n=== SOURCE FILES IN BINLOG ===");
        build.VisitAllChildren<SourceFile>(sf =>
        {
            Console.WriteLine($"  {sf.Name}: {sf.ToString()?.Substring(0, Math.Min(200, sf.ToString()?.Length ?? 0))}");
        });
    }
}
EOF

